/**
* ฟังก์ชันคำนวณผลรวมและอัปเดตค่าในฟิลด์ พร้อมเปลี่ยนสีตามเงื่อนไข
* @param {String} storeId - ID ของ Store ที่ต้องการคำนวณ
* @param {String} fieldId - ID ของฟิลด์ที่ต้องการอัปเดตค่า
*/
function calculateAndUpdateTotal(storeId, fieldId) {
        var gridCmp = Ext.getCmp(storeId);
        var fieldCmp = Ext.getCmp(fieldId);
        if (!gridCmp || !fieldCmp || !gridCmp.getStore) {
                return 0;
        }
        let store = gridCmp.getStore(); // ดึง Store จาก Component ที่ระบุ
        let sumTotal = 0;
        // วนลูปผ่านทุก record ใน store
        store.each(function (record) {
                let f_net_total = parseFloat((record.get("f_net_total") || "0").toString().replace(/,/g, "")) || 0;
                sumTotal += f_net_total;
        });
        // อัปเดตค่าผลรวมในฟิลด์
        fieldCmp.setValue(Ext.util.Format.number(sumTotal, "0,000.00"));
        var fieldEl = fieldCmp.getEl ? fieldCmp.getEl() : null;
        // เงื่อนไขการเปลี่ยนสีของฟิลด์
        if (sumTotal > 0) {
                if (fieldEl) fieldEl.setStyle("color", "green"); // สีเขียวถ้าผลรวมเป็นบวก
        } else if (sumTotal < 0) {
                if (fieldEl) fieldEl.setStyle("color", "red"); // สีแดงถ้าผลรวมเป็นลบ
        } else {
                if (fieldEl) fieldEl.setStyle("color", "orange"); // สีเหลืองถ้าผลรวมเป็น 0
        }
}
