Ext.resetTransfTotal = function (recalculate) {
        var field = Ext.getCmp("f_sum_Transf");
        if (field) {
                field.setValue("0.00");
                var el = field.getEl ? field.getEl() : null;
                if (el) el.setStyle("color", "orange");
        }
        if (recalculate && Ext.getCmp("gridSub4ID")) {
                calculateAndUpdateTotal("gridSub4ID", "f_sum_Transf");
        }
};
Ext.handleZeroTransfAfterRender = function () {
        var field = Ext.getCmp("f_sum_Transf");
        var periodWindow = Ext.getCmp("winPeriodHdrID");
        if (!field || !periodWindow)
                return;
        var total = parseFloat((field.getValue() || "0").toString().replace(/,/g, "")) || 0;
        var recordKey = Ext.selectRow ? Ext.selectRow.get("sp_check_period_hdr_id") : null;
        if (total === 0) {
                var messageBoxRe = Ext.getCmp("MessageBox_re");
                if (messageBoxRe)
                        messageBoxRe.destroy();
                Ext.Msg.alert("แจ้งเตือน", "ค่าการคำนวณผิดพลาด", function () {
                        var win = Ext.getCmp("winPeriodHdrID");
                        if (win)
                                win.destroy();
                });
                return;
        }
        if (total !== 0) {
                if (Ext.zeroTransfReopenKey === recordKey)
                        Ext.zeroTransfReopenKey = null;
                return;
        }
};
