Percentage = function (f_total, perc, name, sh, input) {
        // f_total เงิน
        // perc  เปอร์เซ็น
        // name ชื่อ
        // sh  show or hide
        // input  input = 1  inputValue
        if (input == 1) {
                Ext.getCmp(name).getValue().inputValue;
        } else {
                Ext.getCmp(name).getValue();
        }
};
