const bookingOverlap = function (i, link) {
        var ii = i;
        Ext.getCmp("winDcExpTypeDdd2ID").hide();
        Ext.getCmp("winChequeID").getEl().mask("Please wait...", "x-mask-loading");
        Ext.Ajax.request({
                url: link,
                method: "GET", //POST
                disableCaching: false,
                success: function (result, request) {
                        let jsonData = Ext.util.JSON.decode(result.responseText); //decode json
                        if (ii === 2) {
                                Ext.Ajax.request({
                                        url: "tor/api/mnTorController.php",
                                        params: {
                                                mode: "UPDATE_CONTRACT_BG_OVERLAP2_CHECK", //UPDATE_TOR_DTL_BG
                                                sp_check_period_hdr_id: Ext.rec.get("id"), //sp_dtl_id
                                                bg_reserve_overlap_id: jsonData.bg_reserve_overlap_id,
                                        },
                                        method: "POST", //POST
                                        success: function (result, request) {
                                                Ext.getCmp("winDcExpTypeDdd2ID").destroy();
                                                Ext.getCmp("winChequeID").getEl().unmask(); //end
                                                Ext.storePeriodHdr.reload();
                                        },
                                        failure: function (result, request) {
                                                Ext.MessageBox.alert("Failed", result.responseText); // connect error
                                        },
                                });
                        } else {
                                Ext.Ajax.request({
                                        url: "tor/api/mnTorController.php",
                                        params: {
                                                mode: "UPDATE_CONTRACT_BG_OVERLAP_CHECK", //UPDATE_TOR_DTL_BG
                                                sp_check_period_hdr_id: Ext.rec.get("id"), //sp_dtl_id
                                                c_overlap: Ext.getCmp("c_bookingID").lastSelectionText,
                                        },
                                        method: "POST", //POST
                                        success: function (result, request) {
                                                Ext.getCmp("winDcExpTypeDdd2ID").destroy();
                                                Ext.getCmp("winChequeID").getEl().unmask(); //end
                                                Ext.storePeriodHdr.reload();
                                        },
                                        failure: function (result, request) {
                                                Ext.MessageBox.alert("Failed", result.responseText); // connect error
                                        },
                                });
                        }
                },
                failure: function (result, request) {
                        Ext.MessageBox.alert("Failed", result.responseText); // connect error
                },
        });
};
const genLinkBg = function (event, rec) {
        let link = null;
        //TEST
        let setYear = 0; // product 0 test 1;
        var overlap2Checkbox = Ext.getCmp("use_contract_overlap2ID");
        var useContractOverlap2 = (overlap2Checkbox && overlap2Checkbox.getValue() === true) || Ext.useContractOverlap2 === true;
        var selectedOverlapYear = useContractOverlap2
                ? parseInt(Ext.selectRow.get("i_yyyy_overlap2"), 10)
                : null;
        var selectedOverlapCode = useContractOverlap2
                ? Ext.selectRow.get("c_overlap2")
                : null;
        //END TEST
        switch (event) {
                case "c_overlap":
                        link =
                                Ext.getApiBgBaseUrl() +
                                "/?/bg/BgBudgetAllSupplies2" +
                                "/i_year/" +
                                (parseInt(rec.get("i_yyyy")) - setYear - 543) + //((parseInt(rec.get('i_yyyy')) - setYear)-543)   test +1
                                "/dc_expense_budget_type_id/" +
                                rec.get("dc_expense_budget_type_id") +
                                "/dc_cost_id/" +
                                rec.get("dc_cost_id") +
                                "/bg_expense_id/" +
                                rec.get("po_expense_id") +
                                "/c_code_overlap/" +
                                encodeURIComponent(Ext.getCmp("c_bookingID").lastSelectionText) +
                                "/";
                        break;
                case "c_overlap_book":
                        link =
                                Ext.getApiBgBaseUrl() +
                                "/?/bg/mn_BgReserveMoney/mode/POST" +
                                "/i_sys/" +
                                Ext.session.i_sys +
                                "/pr_id/" +
                                rec.sp_tor_id +
                                "/po_id/" +
                                rec.sp_tor_contract_id +
                                "/chk_id/" +
                                rec.id +
                                "/i_year/" +
                                (useContractOverlap2 ? selectedOverlapYear : (parseInt(rec.i_yyyy) - setYear)) +
                                "/i_pr_type/" +
                                rec.i_pr_type1 + //  plan or period
                                "/i_reserve/3" + // step 1 PR step 2 po step3 checking
                                "/dc_cost_id/" +
                                rec.dc_cost_id +
                                "/dc_budget_type_id/" +
                                rec.dc_expense_budget_type_id +
                                "/bg_expense_id/" +
                                rec.po_expense_id +
                                "/i_last/" +
                                (rec.i_type_contract === 3 ? 0 : 1) + // pr มี สัญญาเดียว = 1
                                "/c_code_overlap/" +
                                encodeURIComponent(useContractOverlap2 ? selectedOverlapCode : Ext.getCmp("c_bookingID").lastSelectionText) +
                                "/f_amt/" +
                                Ext.getApiBgAmount(Ext.getCmp("f_totalID").getValue());
                        break;
                case "c_overlap_close":
                        link =
                                Ext.getApiBgBaseUrl() +
                                "/?/bg/mn_BgReserveMoney/mode/POST" +
                                "/i_sys/" +
                                Ext.session.i_sys +
                                "/pr_id/" +
                                rec.sp_tor_id +
                                "/po_id/" +
                                rec.sp_tor_contract_id +
                                "/chk_id/" +
                                rec.id +
                                "/i_year/" +
                                (useContractOverlap2 ? selectedOverlapYear : (parseInt(rec.i_yyyy) - setYear)) +
                                "/i_pr_type/" +
                                rec.i_pr_type1 + //  plan or period
                                "/i_reserve/3" + // step 1 PR step 2 po step3 checking
                                "/dc_cost_id/" +
                                rec.dc_cost_id +
                                "/dc_budget_type_id/" +
                                rec.dc_expense_budget_type_id +
                                "/bg_expense_id/" +
                                rec.po_expense_id +
                                "/i_last/" +
                                rec.i_is_last + //
                                "/c_code_overlap/" +
                                encodeURIComponent(useContractOverlap2 ? selectedOverlapCode : rec.c_contract_overlap) +
                                "/f_amt/" +
                                Ext.getApiBgAmount(Ext.getCmp("f_totalID").getValue());
                        break;
        }
        return link;
};
