// Helper function to update d_update field with current date
// Helper function to save current d_update value to database without modifying it
var saveCurrentModifyDate = function () {
        if (!Ext.selectRow) {
                return;
        }

        // ดึงค่า d_update จากแท็บแรกที่มีค่า
        var currentValue = '';
        var tabPanel = Ext.getCmp('tabpanel-edit-custom');
        if (tabPanel) {
                Ext.each(tabPanel.items.items, function (tab) {
                        if (tab.getForm && !currentValue) {
                                var field = tab.getForm().findField('d_update');
                                if (field) {
                                        currentValue = field.getValue() || '';
                                }
                        }
                });
        }

        // ถ้ามีค่า ให้บันทึกลงฐานข้อมูล
        if (currentValue) {
                Ext.Ajax.request({
                        url: "tor/api/mnCheckingController.php",
                        method: 'POST',
                        params: {
                                mode: 'updateModifyDate',
                                action: 'updateModifyDate',
                                d_update: currentValue,
                                sp_tor_id: Ext.selectRow.get('sp_tor_id'),
                                sp_tor_contract_id: Ext.selectRow.get('sp_tor_contract_id')
                        },
                        success: function (response) {
                                console.log('Modify date saved on close');
                        },
                        failure: function (response) {
                                console.error('Failed to save modify date on close:', response);
                        }
                });
        }
};
var updateModifyDate = function (fieldLabel) {
        var d = new Date();
        var day = String(d.getDate()).padStart(2, '0');
        var month = String(d.getMonth() + 1).padStart(2, '0');
        var year = d.getFullYear() + 543;
        var dateStr = day + '-' + month + '-' + year;
        // สร้างข้อความ: "วันที่ * อัพเดท..."
        var updateMsg = dateStr;
        if (fieldLabel) {
                updateMsg = updateMsg + ' * อัพเดท' + fieldLabel + ':';
        }

        // ค้นหา d_update field และอัปเดตค่า ในทุกแท็บ
        var tabPanel = Ext.getCmp('tabpanel-edit-custom');
        if (tabPanel) {
                Ext.each(tabPanel.items.items, function (tab) {
                        if (tab.getForm) {
                                var field = tab.getForm().findField('d_update');
                                if (field) {
                                        // ถ้ามี fieldLabel แสดงว่ากำลังเปลี่ยนฟิลด์ จึงควรอัพเดตความคิดเห็น
                                        if (fieldLabel) {
                                                field.setValue(updateMsg);
                                                // ไฮไลต์สูงเพื่อบ่งชี้อัปเดต
                                                if (field.el && field.el.dom) {
                                                        field.el.dom.style.background = '#FFFFCC';
                                                        setTimeout(function () {
                                                                if (field.el && field.el.dom) {
                                                                        field.el.dom.style.background = '#EEEEEE';
                                                                }
                                                        }, 2000);
                                                }
                                        }
                                }
                        }
                });
        }

        // บันทึก d_update ไปยังฐานข้อมูล
        if (Ext.selectRow) {
                // ดึงค่าจากแท็บปัจจุบัน (ที่มี activeTab)
                var currentValue = updateMsg;
                var tabPanel = Ext.getCmp('tabpanel-edit-custom');
                if (tabPanel && tabPanel.items.items.length > 0) {
                        // ลองดึงจากแท็บ active ก่อน
                        var activeTab = tabPanel.getActiveTab();
                        if (activeTab && activeTab.getForm) {
                                var field = activeTab.getForm().findField('d_update');
                                if (field && field.getValue()) {
                                        currentValue = field.getValue();
                                }
                        }
                }
                if (!Ext.selectRow.data) {
                        Ext.Msg.alert('แจ้งเตือน', 'กรุณาเลือกข้อมูลในตาราง');
                        return;
                }

                Ext.Ajax.request({
                        url: "tor/api/mnCheckingController.php",
                        method: 'POST',
                        params: {
                                mode: 'updateModifyDate',
                                action: 'updateModifyDate',
                                d_update: currentValue,
                                sp_tor_id: Ext.selectRow.get('sp_tor_id'),
                                sp_check_period_hdr_id: Ext.selectRow.get('sp_check_period_hdr_id'),
                                sp_tor_hdr_period_id: Ext.selectRow.get('sp_tor_hdr_period_id'),
                                sp_tor_contract_id: Ext.selectRow.get('sp_tor_contract_id')
                        },
                        success: function (response) {
                                try {
                                        var result = Ext.decode(response.responseText);
                                        console.log('Update modify date saved:', result);
                                } catch (e) {
                                        console.log('Modify date saved to DB');
                                }
                        },
                        failure: function (response) {
                                console.error('Failed to save modify date:', response);
                        }
                });
        }
};
// lightweight custom edit form with tabpanel (added near cellClick to ensure scope)
// =========================
var win_edir_alldata = function (rec) {
        if (!rec || !rec.get || !rec.get('sp_check_period_hdr_id')) {
                Ext.Msg.alert('แจ้งเตือน', 'กรุณาเลือกรายการตรวจรับก่อนเปิดเครื่องมือ');
                return;
        }

        var relationTabs = new Ext.TabPanel({
                activeTab: 0,
                border: false,
                deferredRender: false,
                items: [{
                                title: 'กำลังโหลด',
                                html: '<div style="padding:20px;">กำลังเชื่อมโยงข้อมูลตรวจรับ...</div>'
                        }]
        });
        var relationWindow = new Ext.Window({
                title: 'ข้อมูลเชื่อมโยงรายการตรวจรับ #' + rec.get('sp_check_period_hdr_id'),
                width: 1200,
                height: 650,
                layout: 'fit',
                modal: true,
                maximizable: true,
                constrainHeader: true,
                items: relationTabs,
                buttons: [{
                                text: 'ปิด',
                                handler: function () {
                                        relationWindow.close();
                                }
                        }]
        });
        relationWindow.show();
        relationWindow.getEl().mask('กำลังโหลดข้อมูล...');

        Ext.Ajax.request({
                url: 'tor/api/mnCheckingController.php',
                method: 'POST',
                params: {
                        mode: 'GET_CHECKING_RELATIONS',
                        sp_check_period_hdr_id: rec.get('sp_check_period_hdr_id'),
                        sp_tor_hdr_period_id: rec.get('sp_tor_hdr_period_id'),
                        sp_tor_contract_id: rec.get('sp_tor_contract_id'),
                        sp_tor_id: rec.get('sp_tor_id')
                },
                success: function (response) {
                        relationWindow.getEl().unmask();
                        var result;
                        try {
                                result = Ext.decode(response.responseText);
                        } catch (ex) {
                                Ext.Msg.alert('ผิดพลาด', 'ข้อมูลที่ได้รับจากระบบไม่ถูกต้อง');
                                return;
                        }
                        if (!result.success) {
                                Ext.Msg.alert('ผิดพลาด', result.msg || 'ไม่สามารถโหลดข้อมูลได้');
                                return;
                        }

                        relationTabs.removeAll(true);
                        Ext.each(result.datasets || [], function (dataset) {
                                var fields = [];
                                var columns = [new Ext.grid.RowNumberer({ width: 35 })];
                                Ext.each(dataset.columns || [], function (fieldName) {
                                        fields.push({ name: fieldName });
                                        columns.push({
                                                header: fieldName,
                                                dataIndex: fieldName,
                                                width: 145,
                                                sortable: true,
                                                renderer: function (value) {
                                                        if (value === null || typeof value === 'undefined') {
                                                                return '<span style="color:#999;">NULL</span>';
                                                        }
                                                        return Ext.util.Format.htmlEncode(String(value));
                                                }
                                        });
                                });
                                var datasetStore = new Ext.data.JsonStore({
                                        fields: fields,
                                        data: dataset.rows || []
                                });
                                relationTabs.add(new Ext.grid.GridPanel({
                                        title: dataset.table + ' (' + datasetStore.getCount() + ')',
                                        store: datasetStore,
                                        columns: columns,
                                        stripeRows: true,
                                        autoScroll: true,
                                        loadMask: true,
                                        viewConfig: { forceFit: false },
                                        tbar: [{
                                                        xtype: 'tbtext',
                                                        text: '<b>' + Ext.util.Format.htmlEncode(dataset.title) + '</b>'
                                                }, '->', {
                                                        text: 'Refresh',
                                                        iconCls: 'icon-refresh',
                                                        handler: function () {
                                                                relationWindow.close();
                                                                win_edir_alldata(rec);
                                                        }
                                                }]
                                }));
                        });
                        relationTabs.doLayout();
                        if (relationTabs.items.getCount() > 0) {
                                relationTabs.setActiveTab(0);
                        }
                },
                failure: function () {
                        relationWindow.getEl().unmask();
                        Ext.Msg.alert('ผิดพลาด', 'ไม่สามารถเชื่อมต่อข้อมูลตรวจรับได้');
                }
        });
};

