                                                                        , f_totalID: Ext.getCmp("f_totalID") ? (parseFloat((Ext.getCmp("f_totalID").getValue() || 0).toString().replace(/,/g, "")) || 0) : 0
                                                                        , i_yyyy_overlap: Ext.getCmp("i_yyyy_overlapID") ? Ext.getCmp("i_yyyy_overlapID").getValue() : Ext.selectRow.get("i_yyyy_overlap")
