Ext.onReady(function () {
        Ext.QuickTips.init();
        Ext.AppUx("SP", Ext.codeMenu); //app & show menu

        // if a booking period was open before reload, reopen it now
        var recJson = localStorage.getItem('lastBookingRec');
        if (recJson) {
                try {
                        var recObj = Ext.decode(recJson);
                        var record = new Ext.data.Record(recObj);
                        // delay slightly to ensure viewport/grid ready
                        setTimeout(function () {
                                showCustomEditForm(record);
                        }, 50);
                } catch (e) {
                        console.error('restore booking record', e);
                }
        }

        var App = new Ext.Viewport({
                layout: "border",
                items: new Ext.TabPanel({
                        region: "center",
                        border: false,
                        id: "contenterCenter",
                        defaults: {
                                autoScroll: true,
                                layout: "fit",
                        },
                        listeners: {
                                afterrender: function () {
                                        function loadStorePromise(store) {
                                                return new Promise(function (resolve, reject) {
                                                        // ตรวจสอบก่อนว่าตัวแปรที่ส่งมาเป็น Store จริงไหม
                                                        if (!store || typeof store.load !== 'function') {
                                                                reject('วัตถุที่ส่งมาไม่ใช่ ExtJS Store หรือมีค่าเป็น undefined');
                                                                return;
                                                        }
                                                        // สั่งโหลด Store พร้อมใส่ callback
                                                        store.load({
                                                                callback: function (records, operation, success) {
                                                                        if (success) {
                                                                                resolve(store); // โหลดสำเร็จ ส่งสัญญานไปต่อ
                                                                        } else {
                                                                                reject('ไม่สามารถโหลดข้อมูล Store ได้'); // โหลดพัง ส่งสัญญาณหยุด
                                                                        }
                                                                }
                                                        });
                                                });
                                        }

                                        async function loadAllStores() {
                                                try {
                                                        // 1. เปิด Mask หน้าจอ (ถ้ามีฟังก์ชันนี้ในระบบของคุณ)
                                                        if (Ext.getBody() && typeof Ext.getBody().mask === 'function') {
                                                                Ext.getBody().mask('กำลังโหลดข้อมูลตามลำดับ...');
                                                        }
                                                        console.log('กำลังโหลดอันที่ 1: storeDtl');
                                                        await loadStorePromise(Ext.storeDtl);
                                                        console.log('อันที่ 1 เสร็จแล้ว -> กำลังโหลดอันที่ 2: bg_budget_year');
                                                        await loadStorePromise(Ext.bg_budget_year);
                                                        //                            console.log('อันที่ 2 เสร็จแล้ว -> กำลังโหลดอันที่ 3: Project');
                                                        //                            await loadStorePromise(Ext.storeDtl);
                                                        console.log('โหลดครบทุกอันอย่างสมบูรณ์!');
                                                        // 2. ทำงานที่ต้องการหลังจากทุก Store โหลดเสร็จตรงนี้
                                                        // เช่น initComponent(), refreshGrid()
                                                } catch (error) {
                                                        // ถ้ามี Store ใดโหลดพัง จะกระโดดมาที่นี่ทันที
                                                        console.error('เกิดข้อผิดพลาด:', error);
                                                        Ext.Msg.alert('ข้อผิดพลาด', error);
                                                } finally {
                                                        // ปิด Mask เสมอไม่ว่าจะโหลดสำเร็จหรือพัง
                                                        if (Ext.getBody() && typeof Ext.getBody().unmask === 'function') {
                                                                Ext.getBody().unmask();
                                                        }
                                                }
                                        } //  loadAllStores();

                                        function loadAllStoresWithChain() {
                                                Ext.getBody().mask('กำลังโหลดข้อมูล...');
                                                loadStorePromise(Ext.storeDtl)
                                                        .then(function () {
                                                                console.log('รายการตรวจรับ เสร็จแล้ว');
                                                                return loadStorePromise(Ext.bg_budget_year);
                                                        })
                                                        .then(function () {
                                                                Ext.getBody().unmask();
                                                                Ext.Msg.alert('สำเร็จ', 'ข้อมูลทุกอย่างโหลดเรียงลำดับเสร็จแล้ว');
                                                        })
                                                        .catch(function (error) {
                                                                Ext.getBody().unmask();
                                                                Ext.Msg.alert('ผิดพลาด', 'โหลดข้อมูลล้มเหลว: ' + error);
                                                        });
                                        }
                                        loadAllStoresWithChain();
                                },
                        },
                        items: [new gridMain()],
                }),
        });
        Ext.getCmp("contenterCenter").setActiveTab("tabpanel1");
});
